<span class="line"><span style="color:#E5C07B;">    TOptions</span><span style="color:#61AFEF;"> Get</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">string</span><span style="color:#ABB2BF;">? </span><span style="color:#E5C07B;">name</span><span style="color:#ABB2BF;">);</span></span>
